import jakarta.persistence.*;
import java.util.List;

class N1ProblemDemo {

    // Neu category la @ManyToOne(fetch = FetchType.LAZY), vong lap
    // duoi day van gay N+1: 1 query lay danh sach Product, roi
    // them 1 query rieng cho moi lan p.getCategory().getName() duoc
    // goi lan dau (proxy lazy tu tai du lieu ngay khi truy cap).
    void printCategoryNamesNaively(List<ProductEntity> products) {
        for (ProductEntity p : products) {
            System.out.println(p.getCategory().getName());
        }
    }
}

